codes.map((bird) => {
  // add ebird codes to the export
  bird.EBIRD = scinameEbird.get(bird.SCINAME);
  // Add NFC groups
  if (bird.EBIRD) {
    bird.NFC = ebirdToNFCMap.get(bird.EBIRD);
  }
  // Add SCI4 code
  if (!bird.SP) {
    const [genus, species, subspecies] = bird.SCINAME.split(" ");
    if (subspecies)
      throw new Error(`Subspecies not supported in SCI4 code: ${bird.SCINAME}`);
    bird.SCI4 = `${genus.slice(0, 2).toUpperCase()}${species.slice(0, 2).toUpperCase()}`;
  }

  // Add OldBird URL
  if (oldbird.has(bird.SPEC.toLowerCase()))
    bird.OLDBIRD = oldbird.get(bird.SPEC.toLowerCase())!;
  return bird;
});

export default codes;

const specToBirdMap = new Map<string, BirdCode>();
codes.forEach((bird) => {
  specToBirdMap.set(bird.SPEC, bird);
});

const spec6ToBirdMap = new Map<string, BirdCode>();
codes.forEach((bird) => {
  spec6ToBirdMap.set(bird.SPEC6, bird);
});

const ebirdToBirdMap = new Map<string, BirdCode>();
codes.forEach((bird) => {
  if (bird.EBIRD) {
    ebirdToBirdMap.set(bird.EBIRD, bird);
  }
});

const nfcWithBirds = Object.fromEntries(
  [...nfc.entries()].map(([nfcName, nfcData]) => {
    const birds = nfcData.birds.map((ebirdCode) => {
      if (!ebirdToBirdMap.has(ebirdCode)) {
        console.warn(
          `NFC ${nfcName} has ebird code ${ebirdCode} that is not in the bird codes list.`,
        );
        return null;
      }
      return ebirdToBirdMap.get(ebirdCode);
    });
    return [
      nfcName,
      birds.filter(
        (bird): bird is BirdCode => bird !== null && bird !== undefined,
      ),
    ];
  }),
);

export { specToBirdMap, spec6ToBirdMap, ebirdToBirdMap, nfcWithBirds };
